// The jump map of lean/Jump.lean on BigInt, and the panel of the explainer section "jumps".
// fcStep (the 78 cases of `next` with their step counts) is generated by py/gen_js.py and placed before this file.
// node py/jumps_panel_test.js compares jump() with c/frun.c.
function jump(t, a, b, c) {
  // returns {t, a, b, c, frames, steps, kind, start} or {halt: case name, steps}
  if ((t === "w" || t === "W") && b >= 2n && c >= 1n) {
    const k = b / 2n;
    return {t, a: a + 4n * k, b: b - 2n * k, c, frames: k, steps: 6n * k, kind: "sweep"};
  }
  if ((t === "u" && b >= 1n) || (t === "U" && a >= 1n && b >= 1n)) {
    return {t, a, b: 0n, c: c + 2n * b, frames: b, steps: 4n * b, kind: "sweep"};
  }
  if ((t === "y" || t === "Y") && a >= 3n && c >= 2n) {
    let k = a / 3n; if (c - 1n < k) k = c - 1n;
    return {t, a: a - 3n * k, b: b + 2n * k, c: c - k, frames: 2n * k,
            steps: k * (4n * b + 9n) + 4n * k * (k - 1n), kind: "zigzag"};
  }
  const r = fcStep(t, a, b, c);
  if (r[0] === null) return {halt: FC_NAME[r[5]], steps: r[4]};
  return {t: r[0], a: r[1], b: r[2], c: r[3], frames: 1n, steps: r[4], kind: "case " + FC_NAME[r[5]]};
}

// distance of a zigzag start to the halting rows (0 halts; null when no row of its class exists)
function rowDistance(t, a, b, c) {
  const e = a % 3n, q = a / 3n, odd = (b & 1n) === 1n;
  if (!odd && e === 1n) return c - q - (t === "Y" ? 3n : 2n);
  if (odd && (e === 0n || (e === 2n && t === "y"))) return c - q - 2n;
  return null;
}

if (typeof module !== "undefined") module.exports = {jump, rowDistance};

(function () {
  if (typeof document === "undefined") return;
  const root = document.getElementById("jumpPanel");
  if (!root) return;
  const fmt = (x) => {
    const s = x.toString();
    if (s.length <= 15) return s.replace(/\B(?=(\d{3})+(?!\d))/g, ",");
    return s[0] + "." + s.slice(1, 4) + "&middot;10<sup>" + (s.length - 1) + "</sup>";
  };
  const shape = {
    z: (a, b, c) => `1^${a} (10)^${b} C&gt; 1^${c}`,
    y: (a, b, c) => `1^${a} A&gt; 10 (10)^${b} 1^${c}`,
    w: (a, b, c) => `1^${a} C&gt; 00 (10)^${b} 1^${c}`,
    u: (a, b, c) => `1^${a} (10)^${b} 1 A&gt; 00 1^${c}`,
  };
  let S;
  function reset() {
    S = {t: "z", a: 0n, b: 0n, c: 2n, jumps: 0n, frames: 0n, steps: 2n, halted: null, log: [], best: null, epochs: 0n};
    draw();
  }
  function one() {
    if (S.halted) return false;
    const t0 = S.t, a0 = S.a, b0 = S.b, c0 = S.c;
    const r = jump(S.t, S.a, S.b, S.c);
    S.jumps += 1n;
    if (r.halt) { S.halted = r.halt; S.frames += 1n; S.steps += r.steps + 1n; return false; }
    let note = "";
    if (r.kind === "zigzag") {
      const d = rowDistance(t0, a0, b0, c0);
      if (d !== null) {
        const ad = d < 0n ? -d : d;
        if (S.best === null || ad < S.best.ad || (ad === S.best.ad)) S.best = {ad, jump: S.jumps, a: a0, c: c0, t: t0};
        note = ` (halting row at distance ${d})`;
      }
      if (r.c === 1n) S.epochs += 1n;
    }
    S.log.push(`${fmt(S.jumps)}: ${t0}(${a0}, ${b0}, ${c0}) &rarr; ${r.t}(${r.a}, ${r.b}, ${r.c}), ${r.kind}, ${fmt(r.frames)} frame${r.frames === 1n ? "" : "s"}${note}`);
    if (S.log.length > 14) S.log.shift();
    S.t = r.t; S.a = r.a; S.b = r.b; S.c = r.c; S.frames += r.frames; S.steps += r.steps;
    return true;
  }
  function run(n) { for (let i = 0; i < n; i++) if (!one()) break; draw(); }
  function draw() {
    const big = S.t === S.t.toUpperCase();
    const sh = shape[S.t.toLowerCase()](S.a, S.b, S.c);
    const L = Number(S.a), J = 2 * Number(S.b), R = Number(S.c), T = Math.max(1, L + J + R);
    const bar = (w, cls) => `<span class="jb ${cls}" style="width:${(100 * w / T).toFixed(2)}%"></span>`;
    root.querySelector(".jstate").innerHTML =
      `<b>${S.t}(${S.a}, ${S.b}, ${S.c})</b> = <code>${big ? "1110 " : ""}${sh}</code>`;
    root.querySelector(".jbars").innerHTML = bar(L, "l") + bar(J, "j") + bar(R, "r");
    root.querySelector(".jcount").innerHTML =
      `${fmt(S.jumps)} jumps, ${fmt(S.frames)} frames, ${fmt(S.steps)} machine steps` +
      (S.best ? `; closest halting row so far: distance ${S.best.ad} at jump ${fmt(S.best.jump)}` : "") +
      (S.halted ? `; <b>halted</b> (${S.halted})` : "");
    root.querySelector(".jlog").innerHTML = S.log.join("<br>");
  }
  root.querySelector(".j1").onclick = () => run(1);
  root.querySelector(".j10").onclick = () => run(10);
  root.querySelector(".j1k").onclick = () => run(1000);
  root.querySelector(".j100k").onclick = () => run(100000);
  root.querySelector(".jreset").onclick = reset;
  reset();
})();
